import{_ as i,o as p,c as _,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Ceph BenchOps: Following DevOps Practices for Benchmarking Ceph - Ivo Jimenez, UC Santa Cruz","description":"","frontmatter":{"title":"Ceph BenchOps: Following DevOps Practices for Benchmarking Ceph - Ivo Jimenez, UC Santa Cruz","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","DevOps","Benchmarking","GitHub Actions","Containerization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_BenchOps_-_Following_DevOps_Practices_for_Benchmarking_Ceph_-_Ivo_Jimenez_UC_Santa_Cruz.md","filePath":"posts/2019/Ceph_BenchOps_-_Following_DevOps_Practices_for_Benchmarking_Ceph_-_Ivo_Jimenez_UC_Santa_Cruz.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Ceph_BenchOps_-_Following_DevOps_Practices_for_Benchmarking_Ceph_-_Ivo_Jimenez_UC_Santa_Cruz.md"};function l(o,e,a,r,s,c){return p(),_("div",null,[...e[0]||(e[0]=[t("<p>会议纪要：</p><p>会议主题：简化Ceph项目上线流程</p><p>会议时间：[请填写具体时间]</p><p>会议地点：[请填写具体地点]</p><p>参会人员：Eva Jimenez（加州大学圣克鲁兹分校博士研究生）</p><p>会议内容：</p><ol><li><p><strong>项目背景</strong>：</p><ul><li>由于Graduate of Graduate课程时间较短（仅三个月），学生可用于项目的时间有限。</li><li>目标是简化学生使用Ceph（安全存储）的上线和部署流程。</li></ul></li><li><p><strong>现有工作流程</strong>：</p><ul><li>学生进行围绕Ceph的实验性工作流程。</li><li>目前的流程包括编译Ceph、工作、再次编译等，流程复杂且交互性强。</li></ul></li><li><p><strong>改进措施</strong>：</p><ul><li>引入GitHub Action工作流程，允许用户通过规范语言表达工作流程及执行的操作。</li><li>所有工作流程阶段均容器化，每个操作都在Docker容器中运行。</li><li>提供一个完整的功能性端到端工作流程，学生可以直接开始工作。</li></ul></li><li><p><strong>具体实施</strong>：</p><ul><li>第一个工作流程：构建Ceph并生成所需文件，输出为容器，学生可直接启动容器并运行Bstar进行工作。</li><li>第二个工作流程：支持在云环境中进行基准测试和部署，使用GitHub Action提供的云资源操作。</li><li>使用NSF资助的云平台进行实验。</li><li>工作流程中的所有参数均进行了文档化，方便学生修改和记录。</li></ul></li><li><p><strong>后续计划</strong>：</p><ul><li>开发基于Rook和Ceph的容器化工作流程。</li><li>进一步优化工作流程，提高效率和用户体验。</li></ul></li></ol><p>会议结论：</p><p>通过使用GitHub Action工作流程和容器化技术，可以显著简化Ceph项目的上线和部署流程，提高学生的工作效率和学习体验。后续将重点开发基于Rook和Ceph的容器化工作流程，进一步提升项目质量。</p>",9)])])}const u=i(n,[["render",l]]);export{C as __pageData,u as default};
